def tokens(text):
    text = re.sub('</?[A-Za-z][^>]*>', ' ', html.unescape(str(text or '')))
    return re.findall('[^\\W_]+', unicodedata.normalize('NFKC', text).casefold(), re.UNICODE)

def term_tokens(text):
    return re.findall('[^\\W_]+\\*?', unicodedata.normalize('NFKC', text).casefold(), re.UNICODE)

def evaluate(node, bits):
    if 'term_id' in node:
        return bool(bits & 1 << node['term_id'])
    if 'and' in node:
        return all((evaluate(x, bits) for x in node['and']))
    return any((evaluate(x, bits) for x in node['or']))

def feature_mask(blocks, bits):
    return sum((1 << i for (i, n) in enumerate(['shm', 'civil', 'bridge', 'iot', 'edge']) if evaluate(blocks[n], bits)))

def group_mask(f):
    (s, c, b, i, e) = [bool(f & 1 << k) for k in range(5)]
    values = [s and c, s and b, s and c and i, s and b and i, s and c and e, s and b and e, s and c and i and e, s and b and i and e]
    return sum((1 << k for (k, x) in enumerate(values) if x))

class ScopeMatcher:

    def __init__(self, terms):
        self.nodes = [{'exact': {}, 'wild': {}, 'bits': 0}]
        for term in terms:
            index = 0
            for word in term_tokens(term['text']):
                wildcard = word.endswith('*')
                value = word.rstrip('*')
                node = self.nodes[index]
                if wildcard:
                    key = (value[0], value)
                    cache = node['wild'].setdefault(value[0], {})
                else:
                    key = value
                    cache = node['exact']
                if key not in cache:
                    cache[key] = len(self.nodes)
                    self.nodes.append({'exact': {}, 'wild': {}, 'bits': 0})
                index = cache[key]
            self.nodes[index]['bits'] |= 1 << term['id']

    def match(self, text):
        active = []
        bits = 0
        for word in tokens(text):
            nxt = []
            for idx in active + [0]:
                node = self.nodes[idx]
                child = node['exact'].get(word)
                if child is not None:
                    nxt.append(child)
                    bits |= self.nodes[child]['bits']
                for ((_, prefix), child) in node['wild'].get(word[0], {}).items():
                    if word.startswith(prefix):
                        nxt.append(child)
                        bits |= self.nodes[child]['bits']
            active = nxt
        return bits

    def many(self, items):
        result = 0
        for item in items:
            result |= self.match(item)
        return result

def select_keyword_channels(channels, documentary, model):

    def clean(v):
        if v is None:
            return []
        if not isinstance(v, list):
            raise ValueError('Keyword channel is not an array')
        if any((not isinstance(x, str) for x in v)):
            raise ValueError('Non-text keyword item')
        absent = {'n/a', 'none', 'null', 'nan', 'not available', 'not applicable', 'not provided', 'no keywords'}
        return [x for x in v if tokens(x) and x.strip().casefold() not in absent]
    unknown = set(channels) - set(documentary) - set(model)
    if unknown:
        raise ValueError('Unconfigured keyword channel ' + str(sorted(unknown)))
    normalized = {name: clean(channels.get(name, [])) for name in documentary + model}
    has_documentary = any((normalized[n] for n in documentary))
    chosen = documentary if has_documentary else model
    policy = 'documentary' if has_documentary else 'openalex_fallback' if any((normalized[n] for n in model)) else 'no_keywords'
    return (normalized, [n for n in chosen if normalized[n]], policy)

query = SimpleNamespace(tokens=tokens, Matcher=ScopeMatcher)

class PositionMatcher:

    def __init__(self, texts):
        self.texts = list(texts)
        self.ids = {t: i for (i, t) in enumerate(self.texts)}
        self.base = query.Matcher([dict(id=i, text=t) for (i, t) in enumerate(self.texts)])

    def match(self, text):
        words = query.tokens(text)
        active = []
        hits = {}
        for (at, word) in enumerate(words):
            nxt = []
            for (idx, start) in active + [(0, at)]:
                node = self.base.nodes[idx]
                child = node['exact'].get(word)
                children = [] if child is None else [child]
                children += [kid for ((_, prefix), kid) in node['wild'].get(word[0], {}).items() if word.startswith(prefix)]
                for kid in children:
                    nxt.append((kid, start))
                    bits = self.base.nodes[kid]['bits']
                    while bits:
                        one = bits & -bits
                        i = one.bit_length() - 1
                        hits.setdefault(i, []).append((start, at + 1))
                        bits -= one
            active = nxt
        return (words, hits)

    def ids_for(self, terms):
        return [self.ids[t] for t in terms]

def close(a, b, window):
    return max(0, max(a[0], b[0]) - min(a[1], b[1])) <= window

def evidence(matcher, leaf, text, source, item_index, window):
    (words, hits) = matcher.match(text)
    out = []
    for topic in leaf:
        ctx = [span for i in matcher.ids_for(topic['context_terms']) for span in hits.get(i, [])]
        for role in ['strong_terms', 'weak_terms']:
            for term in topic[role]:
                tid = matcher.ids[term]
                for span in hits.get(tid, []):
                    standalone = source not in ['title', 'abstract'] and term in topic['keyword_standalone'] and (query.tokens(term) == words)
                    specific_ctx = [loc for i in matcher.ids_for(topic.get('term_context_overrides', {}).get(term, topic['context_terms'])) for loc in hits.get(i, [])]
                    excluded = any((matcher.ids[v] in hits for v in topic.get('term_exclusions', {}).get(term, [])))
                    title_acronym = source == 'title' and term in topic.get('title_acronyms', [])
                    guarded = role == 'strong_terms' or ((standalone or title_acronym or any((close(span, x, window) for x in specific_ctx))) and (not excluded))
                    out.append(dict(topic_id=topic['id'], term=term, source=source, item_index=item_index, role=role, guarded=int(guarded), start_token=span[0], end_token=span[1], snippet=' '.join(words[max(0, span[0] - 8):min(len(words), span[1] + 8)])))
    return out

def assign_spans(events, registry):
    lookup = {(r['owner_leaf'], r['term']): r for r in registry}
    bins = collections.defaultdict(list)
    for e in events:
        row = lookup.get((e['topic_id'], e['term']))
        if row and e['guarded']:
            bins[e['source'], e['item_index']].append(dict(e, topic_id=row['topic_id'], owner_leaf=row['owner_leaf']))
    accepted = []
    suppressed = []
    for (key, items) in bins.items():
        items.sort(key=lambda e: (-(e['end_token'] - e['start_token']), -len(e['term'].replace('*', '')), e['term'], e['topic_id'], e['start_token']))
        chosen = []
        for e in items:
            other = next((v for v in chosen if v['topic_id'] != e['topic_id'] and max(v['start_token'], e['start_token']) < min(v['end_token'], e['end_token'])), None)
            if other:
                suppressed.append(dict(e, winning_topic=other['topic_id'], winning_term=other['term']))
            else:
                chosen.append(e)
        accepted += chosen
    return (accepted, suppressed)

def normalize_channels(record):
    channels = dict(record.get('keyword_channels') or {})
    for name in ('author_keywords', 'index_keywords', 'document_keywords'):
        if record.get(name):
            channels[name] = record[name]
    if not channels and record.get('keywords'):
        value = record['keywords']
        if all((isinstance(item, dict) and 'display_name' in item for item in value)):
            channels['openalex_model_keywords'] = [item['display_name'] for item in value]
        else:
            raise ValueError('Unlabelled keyword provenance')
    documentary = [name for name in channels if name in ('author_keywords', 'index_keywords', 'document_keywords', 'historical_author_keywords', 'historical_index_keywords', 'scopus_4_8_author_keywords', 'scopus_4_8_index_keywords') or name.endswith('_documentary_keywords')]
    model = [name for name in channels if name in ('openalex_model_keywords', 'openalex_keywords', 'model_keywords', 'openalex_model')]
    (normalized, chosen, policy) = select_keyword_channels(channels, documentary, model)
    return (normalized, chosen, policy)

def configure_matchers():
    scope = ScopeMatcher(SCOPE_TERMS)
    texts = []
    for leaf in TOPIC_LEAVES:
        for role in ('strong_terms', 'weak_terms', 'context_terms'):
            texts.extend(leaf[role])
        for name in ('term_context_overrides', 'term_exclusions'):
            for values in leaf.get(name, {}).values():
                texts.extend(values)
    topic = PositionMatcher(list(dict.fromkeys(texts)))
    return (scope, topic)

def analyze_record(record, scope, topic):
    (channels, chosen, policy) = normalize_channels(record)
    fields = [('title', 0, record.get('title') or ''), ('abstract', 0, record.get('abstract') or '')]
    for name in chosen:
        fields.extend(((name, index, text) for (index, text) in enumerate(channels[name])))
    mask = scope.many([text for (_, _, text) in fields])
    feature = feature_mask(SCOPE_BLOCKS, mask)
    groups = group_mask(feature)
    domain = None
    themes = set()
    if feature & 1 and feature & 24:
        domain = 'bridge' if feature & 4 else 'other_civil' if feature & 2 else None
    if domain:
        events = []
        for (name, index, text) in fields:
            events.extend(evidence(topic, TOPIC_LEAVES, text, name, index, 35))
        (accepted, _) = assign_spans(events, TOPIC_REGISTRY)
        themes = {event['topic_id'] for event in accepted}
    return {'feature_mask': feature, 'group_mask': groups, 'keyword_policy': policy, 'domain': domain, 'themes': sorted(themes)}
